const intervalMap={};const UPDATE_INTERVAL_MS=5e3;async function updateStatus(status){try{const response=await fetch("/admin/orders_status/"+status.dataset.status,{method:"POST",cache:"no-cache",credentials:"same-origin",headers:{"X-Requested-With":"XMLHttpRequest"},redirect:"follow",referrerPolicy:"no-referrer"});if(!response.ok){throw new Error(`HTTP error! status: ${response.status}`)}const data=await response.text();if(data){status.innerHTML=data;let lazy=document.createElement("script");lazy.src="/assets/"+$version+"/js/lazyload.min.js?v="+Date.now();document.head.appendChild(lazy);executeFunc((()=>{document.querySelectorAll(".offcanvas-link").forEach((function(item){item.addEventListener("click",(function(){offcanvasLink(item)}));item.classList.remove("offcanvas-link")}));return true}),300)}}catch(error){console.error(`[Canban] Ошибка обновления статуса ${status.dataset.status}:`,error)}}function startStatusUpdate(status,intervalMs){const oldInterval=intervalMap[status.dataset.status];if(oldInterval){clearInterval(oldInterval)}async function scheduleUpdate(){await updateStatus(status);const timeoutId=setTimeout(scheduleUpdate,intervalMs);intervalMap[status.dataset.status]={timeoutId:timeoutId,promise:Promise.resolve()}}const startDelay=Math.floor(Math.random()*intervalMs);setTimeout(scheduleUpdate,startDelay)}function stopStatusUpdate(statusKey){if(intervalMap[statusKey]){clearTimeout(intervalMap[statusKey].timeoutId);delete intervalMap[statusKey]}}const canban_statuses=document.querySelectorAll("[data-status][data-level]");for(const status of canban_statuses){updateStatus(status)}for(const status of canban_statuses){startStatusUpdate(status,UPDATE_INTERVAL_MS)}window.addEventListener("pagehide",(function(){Object.keys(intervalMap).forEach((key=>stopStatusUpdate(key)))}));